Function
Role




request(url)
Creates a base request with the target URL


req_method("POST")
Sets the HTTP verb (GET, POST, PUT, DELETE)


req_body_json(data)
Converts data to JSON and sets it as the request body


req_perform()
Sends the assembled request; returns a response object


resp_body_json()
Parses the JSON response body into an R list





Outputs
The server renders vals() and pred() to the UI:

output$vals &lt;- renderPrint(vals())
output$pred &lt;- renderText({
  p &lt;- pred()
  if (is.numeric(p)) round(p, 1) else p
})



Full server


show/hide full server
server &lt;- function(input, output, session) {

  vals &lt;- reactive({
    data.frame(
      bill_length_mm = input$bill_length,
      species = input$species,
      sex = input$sex
    )
  })

  pred &lt;- reactive({
    tryCatch({
      showNotification("Predicting penguin mass...", type = "default", duration = 10)

      response &lt;- httr2::request(api_url) |&gt;
        httr2::req_method("POST") |&gt;
        httr2::req_body_json(vals()) |&gt;
        httr2::req_perform() |&gt;
        httr2::resp_body_json()

      showNotification("Prediction successful!", type = "default", duration = 10)

      response$.pred[[1]]

    }, error = function(e) {
      error_msg &lt;- conditionMessage(e)

      if (grepl("Connection refused|couldn't connect", error_msg, ignore.case = TRUE)) {
        user_msg &lt;- "API not available - is the server running on port 8080?"
      } else if (grepl("timeout|timed out", error_msg, ignore.case = TRUE)) {
        user_msg &lt;- "Request timed out - API may be overloaded"
      } else {
        user_msg &lt;- paste("API Error:", substr(error_msg, 1, 50))
      }

      showNotification(paste("Error:", user_msg), type = "warn", duration = 10)
      paste("Error:", user_msg)
    })
  }) |&gt;
    bindEvent(input$predict, ignoreInit = TRUE)

  output$vals &lt;- renderPrint(vals())
  output$pred &lt;- renderText({
    p &lt;- pred()
    if (is.numeric(p)) round(p, 1) else p
  })
}

shinyApp(ui = ui, server = server)

Logging in Python


Expand to view app-log.py



from shiny import App, render, ui, reactive
import requests
import logging

api_url = 'http://127.0.0.1:8080/predict'
logging.basicConfig(
    format='%(asctime)s - %(message)s',
    level=logging.INFO
)

app_ui = ui.page_fluid(
    ui.panel_title("Penguin Mass Predictor"), 
    ui.layout_sidebar(
        ui.panel_sidebar(
            [ui.input_slider("bill_length", "Bill Length (mm)", 30, 60, 45, step = 0.1),
            ui.input_select("sex", "Sex", ["Male", "Female"]),
            ui.input_select("species", "Species", ["Adelie", "Chinstrap", "Gentoo"]),
            ui.input_action_button("predict", "Predict")]
        ),
        ui.panel_main(
            ui.h2("Penguin Parameters"),
            ui.output_text_verbatim("vals_out"),
            ui.h2("Predicted Penguin Mass (g)"), 
            ui.output_text("pred_out")
        )
    )   
)

def server(input, output, session):
    logging.info("App start")

    @reactive.Calc
    def vals():
        d = {
            "bill_length_mm" : input.bill_length(),
            "sex_Male" : input.sex() == "Male",
            "species_Gentoo" : input.species() == "Gentoo", 
            "species_Chinstrap" : input.species() == "Chinstrap"

        }
        return d

    @reactive.Calc
    @reactive.event(input.predict)
    def pred():
        logging.info("Request Made")
        r = requests.post(api_url, json = vals())
        logging.info("Request Returned")

        if r.status_code != 200:
            logging.error("HTTP error returned")

        return r.json().get('predict')[0]

    @output
    @render.text
    def vals_out():
        return f"{vals()}"

    @output
    @render.text
    def pred_out():
        return f"{round(pred())}"

app = App(app_ui, server)
